content.text:
{
  "name": "Arduino 旋转编码器",
  "name_en": "Arduino Rotary Encoder",
  "manufacturer": "",
  "description": "一种通过 Arduino 采集脉冲信号的旋转编码器或轮速编码器，用于测量轴或车轮的转动、速度与里程变化，常见于小车、机器人和运动控制实验。",
  "description_en": "A rotary or wheel encoder read through an Arduino, used to measure shaft or wheel rotation, speed, and distance changes. It is commonly used in small vehicles, robotics, and motion-control experiments.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "更新编码器的最新转动或速度读数。",
      "description_en": "Update the latest rotation or speed reading from the encoder."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "返回后台采集到的最新编码器读数。",
      "description_en": "Return the latest encoder reading acquired in the background."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止编码器的后台采集。",
      "description_en": "Stop background acquisition from the encoder."
    }
  ],
  "tag_hints": [
    "rotary encoder",
    "wheel speed sensing",
    "odometry",
    "Arduino",
    "pulse counting",
    "robotics",
    "autonomous vehicle"
  ]
}

